<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Application\Usecase\UploadContent;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Connector\FileStorage\BinaryContent;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Service\Visibility\ThemeAssetVisibilityService;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeAssetUploadContentUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeAssetVisibilityService $visibility,
        private readonly ThemeAssetWriteGateway $writer
    ) {
    }

    public function allowUpload(): Allow
    {
        $this->logDebug("Check allow of temp upload Content usecase for Theme asset");
        $span = $this->startSpan("Check allow of temp upload Content usecase for Theme asset");
        try {
            $result = $this->dispatcher->dispatch(new ThemeAssetUploadContentAllowDecision(Allow::allowed('upload', 'Allowed to upload by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function readTemporal(string $query): BinaryContent
    {
        $this->logDebug("Run retrieve temp upload Content usecase for Theme asset");
        $span = $this->startSpan("Run retrieve temp upload Content usecase for Theme asset");
        try {
            $allow = $this->allowUpload();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to read tempora upload for Theme asset');
            }
            return $this->writer->readTemporalContent($query);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function temporalStore(BinaryContent $binary): string
    {
        $this->logDebug("Run temp upload Content usecase for Theme asset");
        $span = $this->startSpan("Run temp upload Content usecase for Theme asset");
        try {
            $allow = $this->allowUpload();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to upload store on Theme asset');
            }
            $this->dispatcher->dispatch(new ThemeAssetUploadContentCheck($binary));
            $input = $this->dispatcher->dispatch(new ThemeAssetUploadContentEnrich($binary, $binary));
            return $this->writer->temporalStoreContent($input->getResult());
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
